public double FindMaxAverage(int[] nums, int k) {
    int best = int.MinValue;
    for (int i = 0; i + k <= nums.Length; i++) {   // n − k + 1 окон
        int sum = 0;
        for (int j = i; j < i + k; j++) sum += nums[j];   // k сложений
        best = Math.Max(best, sum);
    }
    return (double)best / k;
}

