public sealed class FpsCounter : MonoBehaviour {
    const int N = 120;                      // около 2 секунд при 60 FPS
    readonly float[] frames = new float[N];
    int head, count;
    float sum;

    void Update() {
        float dt = Time.unscaledDeltaTime;
        sum += dt - frames[head];           // самое старое уходит, новое входит
        frames[head] = dt;
        head = (head + 1) % N;
        if (count < N) count++;
    }

    public float Fps => sum > 0f ? count / sum : 0f;
}

